from taf.ue.spark.api.facade import Spark
from taf.internal.aliasing import aliasing_scope


class api(object):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    lookup_handler, store = aliasing_scope(lookup_arg='service',
                                           lookup_type=Spark)

    def setup_service(self, host, port=None, alias=None):
        """
        connect to the spark service and create alias-instance mapping

        :param str host: ip address of control pc which the spark service running on
        :param Optional[int] port: spark service listening port, 30999 by default
        :param Optional[str] alias: spark service alias
        """
        port = int(port) if port else None
        spark = Spark(host, port)
        spark.setup()
        self.store.add(spark, alias)
        return spark

    @lookup_handler.implicit_lookup
    def teardown_service(self, service=None):
        """
        disconnect from spark service and clear resources

        :param Optional[Union[str, Spark]] service: spark service name or instance
        """
        service.teardown()

    @lookup_handler.implicit_lookup
    def autocheck(self, until_timeout=None, service=None):
        """
        execute AutoCheck command to detect all the UEs connected

        :param Optional[int] until_timeout: execution timeout in second, 10s by default
        :param Optional[Union[str, Spark]] service: spark service name or instance
        :return: dict
        e.g.
        {
            "CMD": "AutoCheck",
            "Param": {
                   "State": 0, # return 0 if success, otherwise return the error codes
                   "Count": 2  # number of UEs detected, if state is 0.
            }
        }
        """
        until_timeout = int(until_timeout) if until_timeout else None
        return service.AutoCheck(until_timeout=until_timeout).dictionary

