    @lookup_handler.implicit_lookup
    def attach(self, eqindex, uemode, timeout=None, until_timeout=None, service=None):
        """
        execute Attach command to attach UE, running AT+CGATT=1 in behind

        :param int eqindex: UE index, starts from 1 for single specific UE
        :param str uemode: "4G" or "5G_SA" or "5G_NSA"
        :param Optional[int] timeout: timeout(ms) built-in in spark api, 30000 by default
        :param Optional[int] until_timeout: execution timeout in second, 10s by default
        :param Optional[Union[str, Spark]] service: spark service name or instance
        :return: dict
        {
            "CMD": "Attach",
            "EQIndex": 1, # 1 means the first UE,
                          # 2 means the second UE, and so forth.
            "Param": {
                 "State": 0  # return 0 if success, otherwise return the error codes
            }
        }
        """
        until_timeout = int(until_timeout) if until_timeout else None
        timeout = int(timeout) if timeout else 30000
        eqindex = int(eqindex)
        return service.Attach(eqindex, uemode, timeout, until_timeout=until_timeout).dictionary

