    @lookup_handler.implicit_lookup
    def setuppdu(self, eqindex, id, type, apn, ssc_mode=None, s_nssai=None, until_timeout=None, service=None):
        """
        execute SetupPDU command to setup pdu

        :param int eqindex: UE index, starts from 1 for single specific UE
        :param int id: customized pdu id
        :param str type: IP type, e.g. IP, IPV6, IPV4V6
        :param str apn: apn address
        :param Optional[int] ssc_mode: 0-->SSC mode1, 1-->SSC mode2
        :param Optional[str] s_nssai: 5GS fragment information, 16 hexadecimal string,
        the range of the character value is, 0-9, A-F,a-f
        :param Optional[int] until_timeout: execution timeout in second, 10s by default
        :param Optional[Union[str, Spark]] service: spark service name or instance
        :return: dict
        e.g.
        {
            "CMD": "SetupPDU",
            "EQIndex": 1,  # {1~n}, 1 means the first UE, 2 means the second UE, and so forth.
            "Param": {
                   "State": 0  # return 0 if success, otherwise return the error codes
            }
        }
        """
        until_timeout = int(until_timeout) if until_timeout else None
        eqindex = int(eqindex)
        id = int(id)
        ssc_mode = int(ssc_mode) if ssc_mode else None

        return service.SetupPDU(eqindex, id, type, apn, ssc_mode, s_nssai, until_timeout=until_timeout).dictionary

